select * from TblMasterMail

update TblMasterMail set Body=
'<div style="font-family: Calibri; font-size: small; color: #000000">    <table style="width: 100%; font-family: Calibri; font-size: 15px;" bgcolor="White">   <tr>      <td bgcolor="White" height="25" rowspan="1" style="color: #0033CC; background-color: #FFFFFF;">     Dear  <Supervisor Name>  ,      </td>     </tr>   <tr>   <td bgcolor="White" height="25" rowspan="1" style="color: #0033CC; background-color: #FFFFFF;">    HexaVarsity is reaching out to you to understand the effectiveness of the training programs attended by your team members. This will help us understand how effective the training program/s have been and to what extent the identified training objectives were met as a result of the training.<br>    </td>     </tr>   <tr>   <td bgcolor="White" height="25" style="color: #0033CC; background-color: #FFFFFF;">   <br>Please spare few minutes of your valuable time to complete the training effectiveness survey form.<br>   <br>Please rate as per the scale given in the form (shown below):   </td>   </tr>   <tr>   <td height="25">    <!--<div style="width:450px; border:1px solid black; background-color:#c5d9f1; padding:10px 10px 0px 10px;">-->    <table style="font-family: Calibri; font-size: small; width:500px; border:1px solid black; background-color:#c5d9f1; padding:10px 10px 0px 10px;">     <tr>     <td>     <b>Please enter rating on a scale of 1 (Lowest) to 5 (Highest)  based on the parameters: </b>     <ul>      <li>Objectives of the Training course met </li>      <li>Problem solving ability </li>      <li>Programming skill / ability </li>      <li>Communication\Writing Skill Ability </li>      <li>Performance of Members after Training </li>      <li>Behavioural skill </li>     </ul>     </td>     </tr>    </table>   </td>   </tr>   <tr>   <td>   <p style="color: #0033CC; background-color: #FFFFFF;"><i>Note: Please give the necessary remarks or comments wherever applicable and while giving the remarks, please be specific.</p>   </td>   </tr>   <tr>   <td bgcolor="White" height="25" style="color: #0033CC; background-color: #FFFFFF;">   <br>Please use the following link to give feedbacks for your <Singlerorplural>.   </td>   </tr>   <tr>   <td bgcolor="White" height="25" style="color: #0033CC; background-color: #FFFFFF;">   LAN URL:<a href="http://StationH/TrainingFeedback/Account/Login.aspx">http://StationH/TrainingFeedback/Account/Login.aspx</a>   </td>   </tr>   <tr>   <td bgcolor="White" height="25" style="color: #0033CC; background-color: #FFFFFF;">   Internet :<a href="https://stationh.hexaware.com/TrainingFeedback/Account/Login.aspx">https://stationh.hexaware.com/TrainingFeedback/Account/Login.aspx</a>   </td>   </tr>   <tr>   <td bgcolor="White" height="25" style="color: #0033CC; background-color: #FFFFFF;">   <B>NOTE: Please provide your Rating under Training Effectiveness->Supervisor Feedback->Click on Record Rating.</B>    </td>   </tr>   <tr>   <td bgcolor="White" height="25" style="color: #0033CC; background-color: #FFFFFF;">   The <strong style="color: Red">User ID </strong>and <strong style="color: Red">Password  </strong>are as same as your Corp credentials.     </td>   </tr>   <tr>   <td bgcolor="White" height="25" style="color: #0033CC; background-color: #FFFFFF;">  <br/> </td>   </tr>   <tr>   <td bgcolor="White" style="color: #0033CC; background-color: #FFFFFF;" class="style1">   </td>   </tr>   <tr>   </td>  </tr>  <tr>  <td bgcolor="White" height="20" style="color: #FF0909; background-color: #FFFFFF;">  Note:- This is auto generated mail from HEXAVARSITY.  </td>  </tr>  </table>  </div>'
where TYPE=2

